/** Replace a canonical file only after its complete bytes reach the filesystem.
 * The upstream per-owner queue still serializes apply/undo; a failed write or
 * pre-rename process crash never truncates the previous canonical file. */
async function writeCanonical(path, contents) {
    const staging = `${path}.${randomUUID()}.tmp`;
    try {
        await writeFile(staging, contents, { encoding: "utf8", flag: "wx", flush: true });
        await rename(staging, path);
    }
    finally {
        await rm(staging, { force: true });
    }
}
